def is_valid(arr):
    for i in range(len(arr)):
        if i < len(arr) - 2 and arr[i] < arr[i + 1] < arr[i + 2]:
            return False
    return True

def find_sequences(remaining, current_sequence):
    if len(remaining) == 0:
        if is_valid(current_sequence):
            return 1
        return 0

    total_sequences = 0
    for num in remaining:
        new_remaining = remaining[:]
        new_remaining.remove(num)
        total_sequences += find_sequences(new_remaining, current_sequence + [num])
